-- Mallorca: hand-checked places for the new nomad towns (Sóller, Pollença, Port de Pollença, Alcúdia,
-- Port d'Andratx, Peguera, Santa Ponça, Palmanova, Valldemossa, Esporles, Santa Maria del Camí, Inca,
-- Sineu, Artà, Cala Ratjada, Manacor, Felanitx, Santanyí, Ses Salines, Campos, Platja de Palma) and
-- for Palma: coworking spaces, laptop-friendly cafes and municipal libraries.
--
-- Researched in November 2026 from each venue's own website and official pages (town halls, Bibliopalma,
-- Xarxa de Biblioteques de les Illes Balears), then checked a second time by an independent pass that re-opened
-- every source (checked_on 2026-11-15). Prices and hours are the ones published there; where sources
-- disagreed or nothing was published, hours stay empty and the access note says "check before going".
-- Coordinates: Nominatim / OpenStreetMap (ODbL). Coworkings only open to local businesses, hotel guests
-- or residents, closed venues and places that could not be placed on the map were left out. Colivings are in
-- scripts/data/colivings.json (import-colivings.mjs).
--
-- A place that is already on the map (an OpenStreetMap place of the same category within 15 m, a library within
-- 60 m, or any place within 200 m with a similar name) is enriched instead of duplicated: the curated fields are written to that
-- row and locked, so the crawler keeps them. Everything else is added as source 'admin'. Cities that
-- have not been imported yet are skipped, so it is safe to run again after import-cities.mjs and the first
-- crawl. Idempotent; never touches places of other categories or admin rows of another kind.

create or replace function pg_temp.mallorca_nk(t text)
returns text
language sql
immutable
as $$
  select regexp_replace(
    lower(translate(t, 'áàâäéèêëíìîïóòôöúùûüçñÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÇÑ', 'aaaaeeeeiiiioooouuuucnAAAAEEEEIIIIOOOOUUUUCN')),
    '[^a-z0-9]', '', 'g'
  )
$$;

do $mallorca$
declare
  it record;
  v_city uuid;
  v_id uuid;
  v_osm boolean;
  v_matched uuid[] := '{}';
  v_lock text[];
begin
  perform set_config('cosurfing.bulk', 'on', true);
  for it in
    select * from jsonb_to_recordset($items$[
{"slug":"cocowork-alcudia-beach-alcudia","city":"alcudia","name":"CoCowork Alcúdia Beach","category":"coworking","description":"Coworking on Carrer dels Fassers in Port d'Alcúdia, about 50 m from the beach, with 600 Mb Wi-Fi, ergonomic chairs, air conditioning, a meeting room for eight, a small kitchen and a shower. Pets are welcome. Open Mon-Fri 09:00-18:00. Prices (website, excl. VAT): day 20 EUR, 5 days 90 EUR, fixed desk 230 EUR/month.","address":"Carrer dels Fassers 2, Local B, 07400 Alcúdia","lat":39.82616,"lng":3.11599,"website":"https://coworkalcudiabeach.com/en/","phone":"+34 617 971 520","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"website","day_pass_price_cents":2000,"access":"registration","access_note":"Book in advance (payment link sent by email or WhatsApp); the rates page calls booking recommended. Email info@cocoworkalcudiabeach.com. Mon-Fri 09:00-18:00."},
{"slug":"biblioteca-can-torro-alcudia","city":"alcudia","name":"Biblioteca Can Torró","category":"library","description":"Public library in a historic house in Alcúdia old town (Carrer d'en Serra), run by the Can Torró foundation. Its website advertises free internet access and Wi-Fi, and laptops are welcome. It is open Tuesday to Friday mornings and afternoons and on weekend mornings; closed on Mondays and public holidays.","address":"Carrer d'en Serra 15, 07400 Alcúdia","lat":39.85243,"lng":3.12205,"website":"https://www.cantorro.es/","phone":"+34 971 54 73 11","opening_hours":"Tu-Fr 10:00-14:00,16:00-20:00; Sa,Su 09:30-13:30","hours_source":"website","access":"open","access_note":"Free. Closed Mondays and public holidays. July-August hours may differ: no summer timetable is published, so check before going."},
{"slug":"cafeteria-teatre-arta-arta","city":"arta","name":"Cafeteria Teatre Artà","category":"cafe","description":"Relaxed cafe attached to the Artà theatre, beside a small park, with a terrace, vegan options, a beer list and live music at some events. Free Wi-Fi is reported and laptop use is tolerated. The clientele is mostly local, and opening hours differ between sources.","address":"Carrer de Ciutat 1, 07570 Artà","lat":39.6931,"lng":3.35073,"phone":"+34 971 82 97 00","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Opening hours differ between sources (mornings and evenings, varying by day): check before going."},
{"slug":"cafeteria-chapeau-arta","city":"arta","name":"Cafetería Chapeau","category":"cafe","description":"Traditional village cafe-bar on Carrer de Santa Margalida in Artà, opening early and serving coffee, bocadillos, tapas and homemade cakes, with outdoor seating. Wi-Fi is reported and laptop use is tolerated, and the atmosphere is described as quiet. It is a local bar rather than a dedicated work cafe.","address":"Carrer de Santa Margalida 84, 07570 Artà","lat":39.69207,"lng":3.34476,"phone":"+34 971 83 54 96","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Opening hours differ between sources (early opening, some show Wednesday or Sunday closed): check before going."},
{"slug":"biblioteca-municipal-na-batlessa-arta","city":"arta","name":"Biblioteca Municipal Na Batlessa","category":"library","description":"Artà's municipal library, in the Casa de Cultura Na Batlessa on Carrer de Ciutat. It has a general collection, films, music, periodicals and internet access, and the public computers were renewed in September 2026. Winter hours (from 14 September 2026) are weekday afternoons plus Thursday morning; summer hours are mornings only.","address":"Carrer de Ciutat 1, 07570 Artà","lat":39.69311,"lng":3.35033,"website":"https://arta.cat/ajuntament/fitxaServeis.php?id=103","phone":"+34 971 83 52 67","opening_hours":"Mo-We,Fr 15:30-19:30; Th 11:00-14:00,15:30-19:30","hours_source":"website","access":"open","access_note":"Free, no registration. Summer (about 15 June to 15 September): Mo,We,Th,Fr 10:00-14:00; Tu 16:00-20:00. Closed weekends."},
{"slug":"petit-coworking-cala-ratjada","city":"cala-ratjada","name":"Petit Coworking","category":"coworking","description":"Compact shared office on Carrer de ses Roges in Cala Ratjada with flexible and fixed desks, a six-person meeting room, a kitchen with free water and coffee, and a terrace and porch. The site lists 800 Mbps internet and says the seafront promenade is two minutes' walk away. Prices (website, Nov 2026, excl. 21% VAT): day 20 EUR, 5-day pass 75 EUR, fixed shared desk 180 EUR/month.","address":"Carrer de ses Roges 35, Oficina B, 07590 Cala Ratjada","lat":39.70999,"lng":3.4578,"website":"https://petitcoworking.com","phone":"+34 871 570 526","opening_hours":"Mo-Fr 08:00-18:00","hours_source":"website","day_pass_price_cents":2000,"outdoor_seating":"yes","access":"members","access_note":"Weekdays only, 08:00-18:00, with customer service until 15:00. Reserve via the website."},
{"slug":"redols-coworking-campos","city":"campos","name":"REDOLS Coworking","category":"coworking","description":"Coworking on Carrer d'Antelm Obrador in Campos, about 300 m on foot from the town centre, with 10 individual desks, lockers, a coffee corner with kitchenette and fibre in all rooms. A meeting room for six and an activity room for up to 15 can be booked, and a monitor, keyboard kit and printer can be rented. Free street parking is nearby and the bus station is 500 m away. Prices (website, Nov 2026, excl. VAT): day 20 EUR, week 80 EUR, month 190 EUR.","address":"Carrer d'Antelm Obrador 24 - C2, 07630 Campos","lat":39.43423,"lng":3.01928,"website":"https://redolscoworking.com","phone":"+34 611 599 561","opening_hours":"Mo-Fr 08:00-20:00","hours_source":"website","day_pass_price_cents":2000,"access":"members","access_note":"Book via the website, ideally 24 h ahead; you receive an entry code. Coworking Mon-Fri 08:00-20:00; meeting and activity rooms daily 08:00-20:00."},
{"slug":"biblioteca-municipal-de-campos-campos","city":"campos","name":"Biblioteca Municipal de Campos","category":"library","description":"Municipal library in Campos, on the ground floor of the former Franciscan nuns' building (Ca ses Monges Franciscanes). It has a computer zone, a press corner and a general reading room; a study room (sala d'Estudi) is on the upper floor. Open weekday afternoons until 20:00, plus mornings on Monday, Wednesday and Friday.","address":"Carrer del Pare Alzina 17, 07630 Campos","lat":39.42938,"lng":3.01871,"website":"https://ajcampos.net/ca/arees/biblioteca","phone":"+34 971 65 29 31","opening_hours":"Mo,We,Fr 09:00-13:00,15:00-20:00; Tu,Th 15:00-20:00","hours_source":"website","access":"open","access_note":"Free; a library card is only needed to borrow. Closed weekends. Main entrance on Carrer Pare Alzina; a second entrance from Carrer de sa Síquia goes through the courtyard."},
{"slug":"doble-esporles","city":"esporles","name":"Doble","category":"cafe","description":"Specialty coffee cafe on Passeig del Rei in the centre of Esporles, opened in 2022, serving Barcelona-roasted coffee with breakfast and lunch including vegan options. Free Wi-Fi, laptop-friendly seating, outdoor seating and step-free access are reported. It is a regular stop for cyclists and keeps daytime hours, closed on Wednesdays.","address":"Passeig del Rei 5, 07190 Esporles","lat":39.66785,"lng":2.57788,"wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Closed Wednesday; some sources also show Tuesday closed. Daytime only, closing about 16:00-16:30: check before going."},
{"slug":"biblioteca-municipal-d-esporles-esporles","city":"esporles","name":"Biblioteca Municipal d'Esporles","category":"library","description":"Municipal library in the Sa Fàbrica cultural building in Esporles, with a reading room and computers on the ground floor and an upstairs mezzanine for individual work and consultation. Wi-Fi is reported. It is open weekday afternoons; in the mornings the mezzanine can be used for study, though it is not fully silent.","address":"Carrer Ramon Llull 3, 07190 Esporles","lat":39.66873,"lng":2.57826,"website":"https://www.bibliotecaspublicas.es/esporles/","phone":"+34 971 61 10 00","opening_hours":"Mo-Fr 16:00-20:00","hours_source":"website","access":"open","access_note":"Free. Mo-Fr 16:00-20:00. For morning study ask for the key at the town-hall offices. Sources differ on hours: call before going."},
{"slug":"coworking-felanitx-felanitx","city":"felanitx","name":"Coworking Felanitx","category":"coworking","description":"Small coworking run by two locals on Passeig de la República Argentina in Felanitx, with shared desks, private offices, a meeting room, a kitchen and a back yard. Symmetric 600 Mb fibre and air conditioning are advertised, and public transport stops 9 m away. Prices (website, excl. 21% VAT): day 18 EUR, 5 days 70 EUR, desk 160 EUR/month (140 EUR half-day desk).","address":"Passeig de la República Argentina 31, 07200 Felanitx","lat":39.47475,"lng":3.15207,"website":"https://coworkingfelanitx.com","phone":"+34 616 04 91 92","opening_hours":"Mo-Fr 08:00-20:00","hours_source":"website","day_pass_price_cents":1800,"outdoor_seating":"yes","access":"members","access_note":"Reserve via the website form. Standard access is Monday to Friday 08:00-20:00."},
{"slug":"biblioteca-municipal-joan-estelrich-felanitx","city":"felanitx","name":"Biblioteca Municipal Joan Estelrich","category":"library","description":"Main municipal library of Felanitx, on Carrer d'en Pizà and part of the Mallorca library network. It lists Wi-Fi, computers, printing and work and study spaces. Hours are Monday afternoon and Tuesday to Friday mornings and afternoons; closed at weekends.","address":"Carrer d'en Pizà 13, 07200 Felanitx","lat":39.46908,"lng":3.14753,"website":"https://www.felanitx.org/ca/biblioteques-municipals","phone":"+34 971 58 40 21","opening_hours":"Mo 16:00-19:00; Tu-Fr 09:00-13:00,16:00-19:00","hours_source":"website","access":"open","access_note":"Free, no registration. Closed weekends. No separate summer timetable is published: call 971 584 021 or 621 203 009 in July and August."},
{"slug":"soma-cafe-inca","city":"inca","name":"Soma Café","category":"cafe","description":"Specialty coffee cafe on Plaça d'Orient in Inca, serving espresso, filter and cold brew, breakfast and lunch, with vegan options and tables on the square. Free Wi-Fi and laptop-friendly seating are reported. It is closed Mondays and has shorter weekend hours.","address":"Plaça d'Orient 24, 07300 Inca","lat":39.72169,"lng":2.91271,"phone":"+34 623 94 35 01","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Closed Mondays. Reported hours Tuesday to Friday 09:00-16:00 and weekends 09:00-13:00, but sources differ on weekday closing time: check before going."},
{"slug":"biblioteca-municipal-d-inca-inca","city":"inca","name":"Biblioteca Municipal d'Inca","category":"library","description":"Municipal library on the first floor of the Claustre de Sant Domingo in Inca, with a public study room (sala d'estudi) on the ground floor. One timetable is published for the cloister: weekdays 08:30-20:30 and Saturday mornings until 13:15. In summer it shortens to weekday mornings.","address":"Avinguda de les Germanies 2 (Claustre de Sant Domingo), 07300 Inca","lat":39.72115,"lng":2.90685,"website":"https://incaciutat.com/ajuntament/arees/cultura","phone":"+34 871 91 45 08","opening_hours":"Mo-Fr 08:30-20:30; Sa 08:30-13:15","hours_source":"website","access":"open","access_note":"Free, no registration. From the last day of the school year to 31 August: Mo-Fr 08:30-14:00 only, no Saturday."},
{"slug":"escowork-manacor-manacor","city":"manacor","name":"esCowork Manacor","category":"coworking","description":"Coworking in central Manacor with fixed desks, flexible hot desks (esFlex), meeting rooms (the largest for around twenty people) and a virtual-office address. Day passes and flex packs are bought online; opening hours are not published. Prices (booking site, Nov 2026, tax incl.): day 25 EUR, 5 days 105 EUR, 10 days 165 EUR (packs valid one month), fixed desk 285 EUR/month.","address":"Avinguda d'es Torrent 36, 07500 Manacor","lat":39.56624,"lng":3.20735,"website":"https://escowork.com","day_pass_price_cents":2500,"access":"members","access_note":"Book online: the day pass and flex packs are bought through the website. The day pass covers office hours, which are not published."},
{"slug":"tecnia-work-coworking-manacor-manacor","city":"manacor","name":"tecnia.work Coworking Manacor","category":"coworking","description":"Coworking on Avinguda Fra Juníper Serra in Manacor with individual 170x70 cm desks, ergonomic chairs, personal lockers and power/USB sockets, plus private offices and a meeting room for 6-10 people. A 1 Gb/s symmetric wired and Wi-Fi network, a kitchen area and access seven days a week are advertised. Free street parking is reported to be easy to find and the train station is about 5 minutes away. Prices not published.","address":"Avinguda de Fra Juníper Serra 32, 1r B, 07500 Manacor","lat":39.57369,"lng":3.20196,"website":"https://coworkingmanacor.com","phone":"+34 871 80 99 66","access":"registration","access_note":"Contact first to arrange a visit or booking (form, phone or WhatsApp). Access is advertised Monday to Sunday, but no opening hours are published."},
{"slug":"biblioteca-municipal-de-manacor-manacor","city":"manacor","name":"Biblioteca Municipal de Manacor","category":"library","description":"Municipal library in the Convent cloister (Plaça del Convent) in central Manacor. A ground-floor reading area has newspapers and magazines; the first-floor adult room has Wi-Fi and four internet computers. Laptops are explicitly allowed in the teen area (ages 12-16). Winter hours are weekdays 08:30-14:00 and 16:00-20:00 plus Saturday mornings.","address":"Plaça del Convent s/n (Claustre del Convent), 07500 Manacor","lat":39.56924,"lng":3.20677,"website":"https://www.manacor.org/ca/servei-de-biblioteques","phone":"+34 971 84 91 27","opening_hours":"Mo-Fr 08:30-14:00,16:00-20:00; Sa 09:30-13:30","hours_source":"website","access":"open","access_note":"Free, no registration. Summer: weekday mornings only (08:30-14:00), no Saturday; exact switch dates not stated."},
{"slug":"arabay-coffee-palma","city":"palma","name":"Arabay Coffee","category":"cafe","description":"Flagship coffee shop of the Arabay roasting group at the corner of Carrer del Sindicat and Plaça Major in Palma, spread over three floors with natural light and plenty of seating. It is described as a strong workspace with reliable Wi-Fi, and laptops are reported welcome with power sockets. One review claims the Wi-Fi is switched off in the evening. Runs barista classes.","address":"Carrer del Sindicat 5, 07002 Palma","lat":39.571,"lng":2.65255,"website":"https://www.arabaycoffee.com","phone":"+34 871 037 996","outdoor_seating":"yes","access":"open","access_note":"Corner of Plaça Major. Hours differ between sources (about 07:30-20:00 or 08:00-21:00 daily): check before going."},
{"slug":"batx-specialty-coffee-palma","city":"palma","name":"BATX Specialty Coffee","category":"cafe","description":"Specialty coffee shop (Lot61 roast) on Carrer de l'Arxiduc Lluís Salvador in Palma, physically connected to the Cómodo&Co coworking space. The operator describes fast Wi-Fi, many power outlets and large windows, and says a three-hour laptop stay is fine. It serves bagels, toasts and breakfast and lunch dishes.","address":"Carrer de l'Arxiduc Lluís Salvador 7, 07004 Palma","lat":39.57806,"lng":2.65323,"website":"https://batx.es","phone":"+34 971 71 22 64","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Part of the Cómodo&Co coworking building. Hours reported as weekdays 08:00-16:00 and short weekends, but Sunday is unclear: check before going."},
{"slug":"bacan-specialty-coffee-brunch-palma","city":"palma","name":"Bacán Specialty Coffee & Brunch","category":"cafe","description":"Small specialty coffee and brunch cafe on Carrer del Baró de Santa Maria del Sepulcre in Palma, serving espresso, pour-over, brunch and pastries. Wi-Fi and outdoor seating are reported, and laptop use is tolerated. It is a daytime-only cafe, and no official opening hours could be confirmed.","address":"Carrer del Baró de Santa Maria del Sepulcre 12, bajos 2, 07012 Palma","lat":39.57346,"lng":2.64441,"phone":"+34 623 007 178","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Daytime only; reported to close around 15:00, but no official timetable was found."},
{"slug":"cafe-sibilla-palma","city":"palma","name":"Café Sibil·la","category":"cafe","description":"Large cafe-restaurant on the pedestrian Carrer de Blanquerna in Palma's Nord district, serving breakfast, lunch and dinner, open daily 09:00-24:00. It has a street terrace and a vintage interior with patterned tiles. Stable Wi-Fi and power sockets are reported, though the venue does not advertise them. It fills up at lunchtime.","address":"Carrer de Blanquerna 7, 07003 Palma","lat":39.57848,"lng":2.6508,"phone":"+34 971 20 10 03","opening_hours":"Mo-Su 09:00-24:00","hours_source":"listing","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Walk-in; busy at lunch, so booking is advised for lunch. Open daily 09:00-24:00."},
{"slug":"el-grano-de-cafe-palma","city":"palma","name":"El Grano de Café","category":"cafe","description":"Specialty coffee shop on Carrer de Velázquez in central Palma, serving all-day breakfast, cakes and Animal Coffee Roasters beans, with vegan and gluten-free options. Free Wi-Fi and laptop-friendly seating are reported. Opening hours differ between the venue's site and other sources.","address":"Carrer de Velázquez 12, 07002 Palma","lat":39.57298,"lng":2.65459,"website":"https://elgranodecafe.es","phone":"+34 664 09 86 89","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Opening hours differ between sources (daily from 08:30 on the venue site, 09:30-15:30 on Mondays and Sundays elsewhere): check before going."},
{"slug":"hotto-coffee-lab-palma","city":"palma","name":"Hotto Coffee Lab","category":"cafe","description":"Specialty roastery and brunch cafe with Japanese-influenced dishes on Plaça de Raimundo Clar in Palma, from the team behind Surry Hills. Opens daily 09:00-15:00 and takes no reservations. Free Wi-Fi and laptop-friendly seating are reported, and a 2022 visit noted sockets along the window counter. There is a small outdoor terrace.","address":"Plaça de Raimundo Clar 12, local 3, 07002 Palma","lat":39.57045,"lng":2.65542,"website":"https://surryhillscoffee.com/hotto-coffee-lab-palma/","opening_hours":"Mo-Su 09:00-15:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"No reservations, first come first served; open daily 09:00-15:00. Weekend brunch rushes are the busiest times."},
{"slug":"la-molienda-arxiduc-palma","city":"palma","name":"La Molienda Arxiduc","category":"cafe","description":"Second shop of the Palma specialty roaster La Molienda, in the Nord district a few minutes from Plaça d'Espanya, with concrete floors, wood, plants, large tables and plenty of natural light. Laptops are welcome and free Wi-Fi is offered. Brunch and cinnamon rolls come from the roaster's bakery. Open Mon-Fri 08:00-16:00 and Sat-Sun 08:30-14:00.","address":"Carrer de l'Arxiduc Lluís Salvador 9a, 07004 Palma","lat":39.57836,"lng":2.65341,"website":"https://lamolienda.es/es/coffeeshops/arxiduc/","phone":"+34 623 027 098","opening_hours":"Mo-Fr 08:00-16:00; Sa-Su 08:30-14:00","hours_source":"website","access":"open","access_note":"Walk-in; laptops welcome. Groups can call to book a table."},
{"slug":"mama-carmen-s-palma","city":"palma","name":"Mama Carmen's","category":"cafe","description":"Vegan bakery cafe with specialty coffee on Carrer de Cervantes in Santa Catalina, with outdoor seating. It is described as a freelancer favourite with peaceful corners and good Wi-Fi, and free Wi-Fi is reported, although the venue does not state a laptop policy. Open Sunday to Friday 08:00-15:00 and Saturday 08:00-14:30.","address":"Carrer de Cervantes 21, bajos, 07013 Palma","lat":39.57282,"lng":2.63453,"website":"https://mamacarmen.es/cafeterias/mama-carmens","phone":"+34 871 77 41 25","opening_hours":"Su-Fr 08:00-15:00; Sa 08:00-14:30","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Open Sunday to Friday 08:00-15:00 and Saturday 08:00-14:30. Holiday hours may change: check before going."},
{"slug":"mistral-coffee-house-palma","city":"palma","name":"Mistral Coffee House","category":"cafe","description":"Flagship cafe of Mistral Coffee, Mallorca's first specialty roaster, on Plaça de Weyler a short walk from Passeig del Born. Open Mon-Sat 08:30-17:00 and Sunday 09:00-14:00. Free Wi-Fi and outdoor tables on the square are reported, and the upstairs mezzanine is described as workable with reliable Wi-Fi, though the chairs suit short sessions.","address":"Plaça de Weyler 2A, 07001 Palma","lat":39.57178,"lng":2.64983,"website":"https://mistralcoffee.com/","opening_hours":"Mo-Sa 08:30-17:00; Su 09:00-14:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk-in. The upstairs mezzanine has a window onto the square; its chairs are not ideal for long sessions."},
{"slug":"plumo-palma","city":"palma","name":"Plumo","category":"cafe","description":"Specialty coffee shop and bike rental/workshop on a corner of the quiet Plaça de Quadrado in Palma old town, with vintage bicycles as decoration. Wi-Fi is reported throughout, and the upstairs room is where laptop users sit. Open mornings only (roughly 08:00-14:00 on weekdays, Saturday to 13:00), closed Sunday.","address":"Plaça de Quadrado 1, 07001 Palma","lat":39.56927,"lng":2.65318,"phone":"+34 625 19 14 53","access":"open","access_note":"Mornings only: roughly Monday to Friday 08:00-14:00 and Saturday 09:00-13:00; closed Sunday. Walk-in."},
{"slug":"surry-hills-coffee-palma","city":"palma","name":"Surry Hills Coffee","category":"cafe","description":"Australian-style brunch and specialty coffee cafe on Carrer del Carme in central Palma, run by the team behind Hotto Coffee Lab. Open Mon-Fri 08:00-16:00 and Sat-Sun 09:00-14:00, no reservations. Wi-Fi is reported and the cafe is tagged work-friendly; the entrance, toilet and seating are reported accessible. The venue makes no laptop statement.","address":"Carrer del Carme 12, 07003 Palma","lat":39.57424,"lng":2.65045,"website":"https://surryhillscoffee.com/surry-hills-brunch-palma/","opening_hours":"Mo-Fr 08:00-16:00; Sa,Su 09:00-14:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"No reservations; walk-in. Can be busy at peak brunch times."},
{"slug":"santal-palma","city":"palma","name":"SĀNTAL","category":"cafe","description":"Specialty coffee and brunch cafe in a restored 17th-century windmill on Carrer de la Indústria in Santa Catalina, with a terrace and indoor stone rooms. The venue says it is a good place to work on a laptop and lists Wi-Fi. It is open Friday to Monday 09:00-15:00 only. Weekend brunch gets busy, and the venue suggests quieter weekday times.","address":"Carrer de la Indústria 15, 07013 Palma","lat":39.57457,"lng":2.63864,"website":"https://www.santal.info/en/palmademallorca","phone":"+34 691 279 389","opening_hours":"Fr-Mo 09:00-15:00","hours_source":"website","outdoor_seating":"yes","access":"open","access_note":"Walk-in, first come first served. Closed Tuesday to Thursday. For focused work the venue advises avoiding Saturday and Sunday 10:00-13:00."},
{"slug":"casa-planas-coworking-palma","city":"palma","name":"Casa Planas Coworking","category":"coworking","description":"Coworking membership (Colab) inside Fundació Casa Planas, a contemporary-art and creation centre with studios for culture professionals, on Avinguda de Sant Ferran in Palma. The foundation also rents artist studios, meeting rooms and event rooms by the hour. No day pass is advertised, so it suits monthly use. Prices (website, excl. VAT): Colab 100 EUR/month including a workspace, supplies and 10 h of common spaces.","address":"Avinguda de Sant Ferran 21, 07011 Palma","lat":39.57946,"lng":2.63711,"website":"https://casaplanas.org/","phone":"+34 971 96 67 51","access":"registration","access_note":"Contact info@casaplanas.org; no day pass is published. Check current opening hours before visiting."},
{"slug":"convendum-palma-palma","city":"palma","name":"Convendum Palma","category":"coworking","description":"Coworking centre of the Swedish operator Convendum in a 16th-century building near La Lonja in Palma's old town. It has an open lounge with adjustable desks, meeting rooms, two roof terraces and weekday breakfast (08:00-09:30). Members get 24/7 access with a member card, Wi-Fi, wired internet and free printing. Prices not published; they are given on request.","address":"Carrer dels Apuntadors 4, 07012 Palma","lat":39.56895,"lng":2.64582,"website":"https://convendum.se/en/coworking-space/coworking-space-palma/carrer-del-apuntadors-4/","phone":"+46 10 510 08 88","wheelchair":"yes","outdoor_seating":"yes","access":"members","access_note":"Members have 24/7 access with a member card. Staff on site 08:00-17:00 (days unclear: every day or Mon-Fri). Day-pass terms not published: contact the operator."},
{"slug":"coowo-coworking-mallorca-palma","city":"palma","name":"Coowo Coworking Mallorca","category":"coworking","description":"Coworking in the Son Canals/Llevant area of Palma, a few stops by EMT bus from Plaça d'Espanya. Shared and fixed desks come with 1 Gbit Wi-Fi (advertised), printing and scanning, lockers, a dining area, a shared bathroom with shower and a meeting room for up to 8. Open Mon-Fri 08:00-20:00 and Sat 08:00-14:00. Prices (website, excl. VAT): day 20 EUR, flex desk 120 EUR/month, fixed desk from 190 EUR/month.","address":"Carrer de Son Canals 7, bajos, 07007 Palma","lat":39.57982,"lng":2.66576,"website":"https://www.coowo.es/","phone":"+34 678 826 317","opening_hours":"Mo-Fr 08:00-20:00; Sa 08:00-14:00","hours_source":"website","day_pass_price_cents":2000,"access":"members","access_note":"Ask for a free trial day. Entry by code or RFID key in opening hours; 24/7 access is a paid extra. Reception is on demand."},
{"slug":"cowork-bit-palma","city":"palma","name":"Cowork BIT","category":"coworking","description":"Coworking inside the ParcBIT technology park on the outskirts of Palma, about 13 minutes by metro from Plaça d'Espanya. It sells day passes, hot desks, fixed desks, offices and meeting rooms, with soundproof phone booths and 1 Gb fibre (advertised). Coffee, tea and water are included; the park has over 1,300 free parking spaces. Prices (website, excl. VAT): day pass 29 EUR, hot desk from 180 EUR/month, fixed desk from 240 EUR/month.","address":"Carrer de Galileo Galilei 2, Edifici U, local 10, 07121 Palma","lat":39.63618,"lng":2.63134,"website":"https://coworkbit.es/","phone":"+34 971 37 43 40","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"website","day_pass_price_cents":2900,"access":"members","access_note":"Call ahead to arrange a visit. Smart-door access via app; hot desk and day pass cover Mon-Fri 09:00-18:00, fixed desks 24/7."},
{"slug":"coworking-junts-palma","city":"palma","name":"Coworking Junts","category":"coworking","description":"Small coworking in the Bons Aires area north of Palma's old town, with an open work room, a meeting room for up to 10 and a rest area; coffee and water are included. 1 Gb Wi-Fi is advertised. Fixed and flexible desks come on 4 h, 8 h or 24/7 plans. Prices (website, excl. VAT): day bono 20 EUR, 10 days 90 EUR, flex desk 24/7 120 EUR/month, fixed desk 24/7 175 EUR/month.","address":"Carrer de Pere Martell 44, local 2, 07003 Palma","lat":39.57943,"lng":2.64871,"website":"https://coworkingjunts.es/","phone":"+34 667 604 865","opening_hours":"Mo-Fr 09:00-20:00","hours_source":"website","day_pass_price_cents":2000,"access":"members","access_note":"Bonos give access Mon-Fri 09:00-20:00; 24/7 plans get an electronic key. Reception 09:00-20:00."},
{"slug":"comodo-co-arxiduc-palma","city":"palma","name":"Cómodo&Co Arxiduc","category":"coworking","description":"Second Palma location of Cómodo&Co, near Plaça d'Espanya and the train station. The operator lists flex and dedicated desks, an 8-person meeting room, high-speed Wi-Fi, air conditioning, lockers, phone booths, a kitchen and an in-house cafe (BATX), entered via the cafe. Prices (booking page, Nov 2026): flex desk 15 EUR/day, 49 EUR/week, 125 EUR/month; private desk 35 EUR/day, 119 EUR/week, 235 EUR/month.","address":"Carrer de l'Arxiduc Lluís Salvador 7, 07004 Palma","lat":39.57806,"lng":2.65323,"website":"https://coworking-palma.com/","opening_hours":"Mo-Sa 08:00-22:00","hours_source":"website","day_pass_price_cents":1500,"access":"members","access_note":"Book online (flex desks by the day, week or month). Flex access Mon-Sat 08:00-22:00 via cafe BATX; private desks Mon-Sat 07:00-22:00 with a 24/7 option."},
{"slug":"comodo-co-santa-catalina-palma","city":"palma","name":"Cómodo&Co Santa Catalina","category":"coworking","description":"Coworking in Santa Catalina, Palma, entered through the in-house cafe BATX. It offers flex desks, private desks, virtual offices and phone booths, plus a kitchen, lockers and air conditioning. Flex access is Monday to Saturday 08:00-22:00. Prices (website, Nov 2026, VAT not stated): flex desk 15 EUR/day, 49 EUR/week, 99 EUR/month; private desk 35 EUR/day, from 155 EUR/month.","address":"Carrer d'Espartero 6, 07014 Palma","lat":39.57101,"lng":2.63457,"website":"https://coworking-palma.com/coworking-santa-catalina","opening_hours":"Mo-Sa 08:00-22:00","hours_source":"website","day_pass_price_cents":1500,"access":"members","access_note":"Book online. Flex access Mon-Sat 08:00-22:00, dedicated desks 07:00-22:00, 24/7 option available. Discount at Cafe BATX."},
{"slug":"fortuny3-espai-coworking-palma","city":"palma","name":"Fortuny3 Espai Coworking","category":"coworking","description":"Small coworking in a first-floor flat in Palma's old town, run by the architecture studio Arquit3ctes. The work room has 8 desks with retractable tables and ergonomic chairs; there is also a 25 m2 meeting room for up to 15 people, a kitchen, a small terrace and a patio garden. Cable and Wi-Fi internet are provided, and the work room is accessible 24/7. Prices (Oct 2026, excl. VAT): day 30 EUR, Eco plan 149 EUR/month, Full plan 199 EUR/month.","address":"Carrer de Can Fortuny 3, entresuelo B, 07001 Palma","lat":39.56851,"lng":2.65118,"website":"https://www.fortuny3.es/","phone":"+34 683 36 02 93","day_pass_price_cents":3000,"outdoor_seating":"yes","access":"members","access_note":"Contact by phone or email to book. Desk room open 24/7 for members; meeting room 09:00-18:00."},
{"slug":"fundacio-bit-coworking-palma","city":"palma","name":"Fundació BIT Coworking","category":"coworking","description":"Public coworking of the Fundació BIT innovation foundation in the Naorte building at ParcBIT, with room for 10 desks. It is aimed at freelancers, entrepreneurs and small companies in innovation and technology, and applicants go through the ParcBIT admission process. Prices (2026 tariff, excl. VAT): fixed desk 90 EUR/month for 3 months or more, 110 EUR/month for shorter stays.","address":"Edifici Naorte, Carrer de Blaise Pascal 3, 07121 Palma","lat":39.63684,"lng":2.63101,"website":"https://www.fundaciobit.org/parcbit/","phone":"+34 971 17 60 60","access":"application","access_note":"Application only, no day pass: applicants must pass the ParcBIT admission committee and work in technology/innovation. Contact info@fundaciobit.org."},
{"slug":"moasis-cowork-palma","city":"palma","name":"Moasis Cowork","category":"coworking","description":"Business-centre style coworking on the second floor of Plaça d'Espanya 1 in central Palma. It offers flexible and fixed desks, small offices, a cafe-club area, a conference hall for up to 100 people, a training room, a recording studio and a fitness room. Prices not published; day-pass terms are given on request only.","address":"Plaça d'Espanya 1, 2nd floor, 07002 Palma","lat":39.57579,"lng":2.65274,"website":"https://moasis.es/","phone":"+34 669 81 62 13","access":"members","access_note":"Contact sabrina@moasis.es for a day pass or visit. Opening hours differ between sources: check before going."},
{"slug":"palmapolitan-palma","city":"palma","name":"Palmapolitan","category":"coworking","description":"Coworking in the historic Triquet building on Carrer del Sindicat in central Palma, about 200 m from Plaça d'Espanya intermodal station. It has private-room-style workspaces, a conference room and a kitchen with coffee and tea; the internet is described as fast and reliable for video calls. Prices (operator tariff, Oct 2026): day 25 EUR, week 110 EUR, hot desk 180 EUR/month, fixed desk 250 EUR/month.","address":"Carrer del Sindicat 74, 07002 Palma","lat":39.57226,"lng":2.6563,"website":"https://palmapolitan.com/","phone":"+34 691 784 506","day_pass_price_cents":2500,"access":"members","access_note":"Day passes can be booked online and walk-ins are reported to be accepted. Mon-Fri 09:00-18:00 is reported but not confirmed by the operator: check before going."},
{"slug":"panteon-house-palma","city":"palma","name":"Panteon House","category":"coworking","description":"Shared office on Carrer de Joan Maria Thomàs in Palma with 16 fixed desks, 4 private offices, two meeting rooms free for members, a community kitchen with free coffee and tea, showers and bike racks. Members have 24/7 access. There is no hot-desking or day pass: fixed desks need a minimum 6-month contract and offices 12 months. Prices (website, excl. VAT): fixed desk 250 EUR/month, 4-person office 800 EUR.","address":"Carrer de Joan Maria Thomàs 2-1, 07014 Palma","lat":39.57196,"lng":2.63296,"website":"https://panteon.house/","phone":"+34 971 579 266","opening_hours":"Mo-Fr 08:00-16:00","hours_source":"website","access":"application","access_note":"Fixed-desk contracts only, no day passes. Reception is staffed Mon-Fri 08:00-16:00."},
{"slug":"regus-palma-son-castello-palma","city":"palma","name":"Regus Palma Son Castelló","category":"coworking","description":"Regus business centre on the second floor of Gremi de Sabaters 21 in the Son Castelló industrial estate, roughly 6-7 minutes on foot from Son Castelló metro. It offers coworking desks, private offices, virtual offices and meeting rooms, with on-site parking. It is away from the centre and mainly suits people working in the estate. Prices (excl. tax): day pass from about 25 EUR, coworking desk 149 EUR/month (or 4 EUR/h).","address":"Carrer del Gremi de Sabaters 21, 2º, 07009 Palma","lat":39.5992,"lng":2.66914,"website":"https://www.regus.com/es/es/3792","day_pass_price_cents":2500,"wheelchair":"yes","access":"registration","access_note":"Book through Regus/IWG. 24/7 access for members on private-office and dedicated-desk plans; reception hours not confirmed by the operator."},
{"slug":"spaces-palma-marina-palma","city":"palma","name":"Spaces Palma Marina","category":"coworking","description":"Serviced office and coworking centre of the Spaces (IWG) network on the Paseo Marítimo near Santa Catalina, opened in April 2024. It has meeting rooms, private offices, virtual offices, an outdoor terrace, bicycle storage and wheelchair access, and sells a cowork day pass. Prices (website, 'from' rates, VAT not stated): day pass from 45 EUR, dedicated desk from 9 EUR/day-equivalent, meeting rooms from 35 EUR/h.","address":"Carrer de Monsenyor Palmer 1, 07014 Palma","lat":39.5693,"lng":2.63425,"website":"https://www.spacesworks.com/en/es/7342","phone":"+34 871 55 93 70","day_pass_price_cents":4500,"wheelchair":"yes","outdoor_seating":"yes","access":"registration","access_note":"Cowork day pass is booked online; no walk-in visits without an appointment. 24/7 access applies to private-office and dedicated-desk customers."},
{"slug":"where-to-work-palma-palma","city":"palma","name":"Where to Work Palma","category":"coworking","description":"Business-centre style coworking and serviced office on Carrer del Sindicat in Palma, about a 10-minute walk from the centre. The operator lists 20 workspaces, 10 private offices, a kitchen and a meeting room for up to 10 people. Hot desks, dedicated desks, private and virtual offices are offered, with 24/7 smart-key access for members and printing and mail handling at reception. Prices not published.","address":"Carrer del Sindicat 67, 1º 1ª, 07002 Palma","lat":39.57257,"lng":2.65596,"website":"https://palma.wheretowork.eu/","phone":"+34 871 55 65 11","access":"members","access_note":"Enquire with the operator: no prices or public day-pass terms. Members have 24/7 smart-key entry. Reception hours vary, so call ahead before visiting."},
{"slug":"zulu-coworking-palma","city":"palma","name":"ZULU Coworking","category":"coworking","description":"Coworking in Palma's Santa Catalina district with exposed Mallorcan stone walls and long shared tables giving each person 150 cm. Facilities include standing desks, free lockers, two soundproof phone booths, a meeting room, a kitchen and a courtyard with plants. Desks are booked online by the day, week or month; dogs are allowed. Prices (Nov 2026, excl. VAT): hot desk 30 EUR/day, 130 EUR/week, 230 EUR/month; dedicated desk 280 EUR/month.","address":"Carrer de Sant Magí 72, 07013 Palma","lat":39.57056,"lng":2.63616,"website":"https://zulucoworking.com/","phone":"+34 621 191 345","opening_hours":"Mo-Fr 08:30-19:00","hours_source":"listing","day_pass_price_cents":3000,"wheelchair":"yes","access":"members","access_note":"Book online; a free visit is available. Open Mon-Fri 08:30-19:00; 24/7 digital-key access depends on the prepaid plan."},
{"slug":"ewave-coworking-mallorca-palma","city":"palma","name":"eWave Coworking Mallorca","category":"coworking","description":"Coworking and start-up incubator in Es Molinar, Palma, about 100 m from the sea and the seafront cycling and running path. It has wooden tables, plants, a terrace, a kitchen with free tea and coffee, bike storage and showers, and Wi-Fi is included in all memberships. Options are a Mon-Fri flex pass (08:00-20:00), resident desks with a 24/7 option, and day or 5-day passes on request. Prices not published.","address":"Carrer de Llucmajor 75, 07006 Palma","lat":39.55951,"lng":2.6765,"website":"https://ewavemallorca.com/","phone":"+34 659 86 71 20","opening_hours":"Mo-Fr 08:00-20:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"members","access_note":"Request a day or 5-day pass via the website form. Resident desks have a 24/7 option."},
{"slug":"biblioteca-municipal-el-molinar-palma","city":"palma","name":"Biblioteca Municipal El Molinar","category":"library","description":"Municipal library in the Sa Petrolera / Can Salas building in El Molinar, Palma. It has a 24-seat main reading room, a 24-seat multipurpose study room (Aurora Picornell), a press area with armchairs, two public computers and Wi-Fi throughout. Open Monday to Friday 08:30-20:30 and Saturday 09:00-13:00.","address":"Carrer de Francesc Femenias 1, 07006 Palma","lat":39.56218,"lng":2.67066,"website":"https://bibliopalma.palma.es/","phone":"+34 971 225 900 ext. 3660","opening_hours":"Mo-Fr 08:30-20:30; Sa 09:00-13:00","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Saturdays in July and August, and on public holidays and 24 and 31 December. Special exam timetables are published."},
{"slug":"biblioteca-municipal-joan-alcover-palma","city":"palma","name":"Biblioteca Municipal Joan Alcover","category":"library","description":"Municipal library on the second floor of the Casal de Barri in Foners, east of Palma's centre. It has 42 adult reading places, an office area with six internet computers and a press-reading corner. Open weekdays 08:30-20:30 and Saturday mornings. Palma's free municipal Wi-Fi is available after accepting the conditions.","address":"Carrer de Joan Alcover 28, 07006 Palma","lat":39.56867,"lng":2.66017,"website":"https://bibliopalma.palma.es/","phone":"+34 971 771 724","opening_hours":"Mo-Fr 08:30-20:30; Sa 09:00-13:00","hours_source":"website","access":"open","access_note":"Free, no registration. Closed on public holidays and 24 and 31 December; special exam timetables are published. No summer timetable confirmed: check before going."},
{"slug":"biblioteca-municipal-de-cort-palma","city":"palma","name":"Biblioteca Municipal de Cort","category":"library","description":"Municipal library on Plaça de Cort in Palma's old town, the city's oldest municipal library and specialised in local Palma material. It has 34 reading places. Open Monday to Friday 08:30-20:30 and Saturday mornings; closed on Saturdays in July and August.","address":"Plaça de Cort 1, 07001 Palma","lat":39.56908,"lng":2.65043,"website":"https://bibliopalma.palma.es/-/biblioteca-cort-","phone":"+34 971 225 900","opening_hours":"Mo-Fr 08:30-20:30; Sa 09:00-13:00","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Saturdays in July and August; no other summer timetable is published."},
{"slug":"biblioteca-municipal-de-santa-catalina-palma","city":"palma","name":"Biblioteca Municipal de Santa Catalina","category":"library","description":"Neighbourhood municipal library at the corner of Carrer de la Fàbrica and Carrer d'Antich, next to Plaça del Progrés in Palma. It has 20 reading places, two internet computers, Wi-Fi and air conditioning. Open Monday and Friday 08:30-14:30 and Tuesday to Thursday 14:30-20:30; closed on Saturdays.","address":"Carrer de la Fàbrica 34, 07013 Palma","lat":39.57297,"lng":2.63644,"website":"https://bibliopalma.palma.es/","phone":"+34 971 286 069","opening_hours":"Mo,Fr 08:30-14:30; Tu-Th 14:30-20:30","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Saturdays, public holidays and 24 and 31 December. Summer timetable not published: check before going."},
{"slug":"biblioteca-municipal-de-son-canaves-palma","city":"palma","name":"Biblioteca Municipal de Son Cànaves","category":"library","description":"Neighbourhood municipal library in the Son Cànaves (El Secar de la Real) district of Palma, in Plaça de la Sitja. It has 46 reading points. Open Monday and Friday mornings and Tuesday to Thursday afternoons; closed on Saturdays.","address":"Plaça de la Sitja 4, 07010 Palma","lat":39.60885,"lng":2.6386,"website":"https://bibliopalma.palma.es/","phone":"+34 971 225 900 ext. 3659","opening_hours":"Mo,Fr 08:30-14:30; Tu-Th 14:30-20:30","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Saturdays. Summer timetable differs and the branch may close in August; extraordinary exam-period openings are announced by the library network."},
{"slug":"biblioteca-municipal-de-son-ferriol-palma","city":"palma","name":"Biblioteca Municipal de Son Ferriol","category":"library","description":"Municipal library in the Casal de Barri building in Son Ferriol, Palma, described as quiet and designed for study, with 46 reading points. Open Monday and Friday mornings and Tuesday to Thursday afternoons; closed at weekends.","address":"Carrer de Sant Joan de la Creu 43, 07198 Palma","lat":39.57439,"lng":2.71534,"website":"https://bibliopalma.palma.es/","phone":"+34 971 429 856","opening_hours":"Mo,Fr 08:30-14:30; Tu-Th 14:30-20:30","hours_source":"website","access":"open","access_note":"Free, no registration. Closed weekends. Summer timetable differs and some branches close in August: check before going. Exam-period openings are announced."},
{"slug":"biblioteca-municipal-de-l-olivar-palma","city":"palma","name":"Biblioteca Municipal de l'Olivar","category":"library","description":"Small municipal library on the first floor of the Mercat de l'Olivar building in central Palma. It has 12 reading places and one public computer. Open Monday to Friday 08:00-14:00, so weekday mornings only, and Saturday 09:00-13:00.","address":"Plaça de l'Olivar 1, 1r (Mercat de l'Olivar), 07002 Palma","lat":39.57396,"lng":2.65236,"website":"https://bibliopalma.palma.es/","phone":"+34 971 225 900 ext. 3674","opening_hours":"Mo-Fr 08:00-14:00; Sa 09:00-13:00","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Saturdays in July and August, and on public holidays and 24 and 31 December. Special exam timetables are published."},
{"slug":"biblioteca-municipal-de-la-indioteria-palma","city":"palma","name":"Biblioteca Municipal de la Indioteria","category":"library","description":"Small municipal library (about 90 m2) inside the sa Indioteria public school building in Palma. It has study and reading tables with 30 chairs, one public internet computer and a children's area. Open Monday and Friday mornings and Tuesday to Thursday afternoons; closed at weekends.","address":"Carrer del Gremi de Tintorers 2, 07009 Palma","lat":39.60621,"lng":2.6747,"website":"https://bibliopalma.palma.es/","phone":"+34 971 207 505","opening_hours":"Mo,Fr 08:30-14:30; Tu-Th 14:30-20:30","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Saturdays and Sundays. Summer timetable changes and some branches close in August: check before going."},
{"slug":"novacentro-coworking-palmanova","city":"palmanova","name":"Novacentro Coworking","category":"coworking","description":"Fixed-desk coworking in the attic of the Novacentro business centre in Palmanova, with a 100 m2 open space and a terrace overlooking the sea and mountains. Places are limited and each desk has an individual locker. It targets business owners, freelancers and foreign-based companies wanting a permanent base in Mallorca rather than hot-desking. Kitchen, TV meeting rooms, private indoor parking, security system and Wi-Fi are listed. Prices not published.","address":"Carrer de Còrdova 5, 07181 Calvià (Palmanova)","lat":39.52966,"lng":2.53983,"website":"https://nova-centro.com/en/coworking/","phone":"+34 639 163 840","outdoor_seating":"yes","access":"application","access_note":"Fixed desks only, places limited: arrange a visit by phone or info@nova-centro.com. Contact hours Mon-Fri 08:00-21:00 (not confirmed as access hours)."},
{"slug":"biblioteca-magaluf-palmanova","city":"palmanova","name":"Biblioteca Magaluf","category":"library","description":"Municipal library in the Casa de Cultura in Magaluf, about 85 m2 split into reception/periodicals, general and literature areas, opened in 1985. Winter timetable (September to June): Tuesday and Thursday afternoons, Wednesday and Friday mornings, Saturday mornings.","address":"Carrer Puig de sa Mola 23 baixos (Casa de Cultura), 07181 Magaluf","lat":39.50272,"lng":2.52824,"website":"https://bibliotequesdecalvia.com/","phone":"+34 971 13 15 40","opening_hours":"Tu,Th 14:30-20:30; We,Fr 08:30-14:30; Sa 09:00-14:30","hours_source":"website","access":"open","access_note":"Free, no registration. Winter timetable only (Sept-June); July-August hours are not published. Friday opening is uncertain: check before going."},
{"slug":"biblioteca-son-caliu-es-generador-palmanova","city":"palmanova","name":"Biblioteca Son Caliu - Es Generador","category":"library","description":"Municipal library in the Es Generador civic building in Son Caliu (Palmanova), opened in 2008. About 110 m2 with a reception/children's room and an adults' room, two public computers and wifi. Winter timetable (September to June): Monday and Wednesday afternoons, Tuesday and Thursday mornings.","address":"Carrer Voranova 8 (Edifici Es Generador), 07181 Palmanova","lat":39.52774,"lng":2.54319,"website":"https://bibliotequesdecalvia.com/","phone":"+34 971 13 92 09","opening_hours":"Mo,We 14:30-20:30; Tu,Th 09:00-14:30","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Fridays, Saturdays and Sundays. Winter timetable only (Sept-June); July-August hours are not published."},
{"slug":"el-cafe-peguera","city":"peguera","name":"El Cafè","category":"cafe","description":"Neighbourhood cafe-bar on Carrer de la Savina in Peguera, serving breakfast, toasts and sandwiches from early morning, with a street terrace facing the Tuesday market. It is tagged as good for working on a laptop and reported to have a step-free entrance and seating. Wi-Fi is not confirmed, so ask before settling in.","address":"Carrer de la Savina 1, 07160 Peguera","lat":39.53752,"lng":2.44447,"phone":"+34 971 15 31 34","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Reported open Mon-Sat 06:00-24:00, closed Sunday; some sources differ. A street market is held in front of the cafe on Tuesdays."},
{"slug":"aethos-mallorca-coworking-lounge-peguera","city":"peguera","name":"Aethos Mallorca Coworking Lounge","category":"coworking","description":"Co-working lounge inside Aethos Mallorca, a cliff-top hotel and members' club at Cala Fornells in Peguera, opened in summer 2025 in a restored former monastery. Use of the space requires an Aethos club membership; no day pass is published. Annual memberships: Connect 650 EUR/yr (6 visits per club), One 175 EUR/month or 1,800 EUR/yr, Unlimited 240 EUR/month or 2,500 EUR/yr.","address":"Carrer Mareselva 2, 07160 Peguera","lat":39.53667,"lng":2.44844,"website":"https://www.aethos.com/clubs/mallorca","phone":"+34 660 571 418","outdoor_seating":"yes","access":"members","access_note":"Membership required (all standard memberships are annual). Whether hotel guests can use the co-working space is not stated: ask. Enquire via mallorca@aethos.com."},
{"slug":"biblioteca-peguera-peguera","city":"peguera","name":"Biblioteca Peguera","category":"library","description":"Municipal library in Peguera, in a single room of about 100 m2 near the health centre, opened in 1991. Reading in the room and wifi are offered, but seating is not detailed. Winter timetable (September to June): Tuesday and Thursday afternoons, Wednesday, Friday and Saturday mornings.","address":"Carrer Malgrats 17 baixos, 07160 Peguera","lat":39.53894,"lng":2.44801,"website":"https://bibliotequesdecalvia.com/biblioteca-de-peguera/","phone":"+34 971 68 55 37","opening_hours":"Tu,Th 14:30-20:30; We,Fr 08:30-14:30; Sa 09:00-14:30","hours_source":"website","access":"open","access_note":"Free, no registration. Winter timetable only (Sept-June); July-August hours are not published. Saturday opening is uncertain: check before going."},
{"slug":"baysense-coworking-platja-de-palma","city":"platja-de-palma","name":"Baysense Coworking","category":"coworking","description":"Coworking complex at Playa de Palma spread over three locations (about 1,600 m2) with flex desks, private offices with 24/7 access, meeting rooms and a 162 m2 business lounge. 'Superfast' internet (advertised), printers, water, coffee, showers and free parking are listed as included; pets are allowed. The beach is a minute away. Prices (website, plus VAT): flex desk 39 EUR/day (Mon-Fri), private office 595 EUR/month.","address":"Carrer de Marbella 17, local 48, 07610 Platja de Palma","lat":39.5274,"lng":2.73446,"website":"https://baysense.es/","phone":"+34 620 734 428","day_pass_price_cents":3900,"access":"members","access_note":"Flex desk available Mon-Fri only; weekends and holidays need a monthly pass. Private offices have 24/7 access. Book via the contact form or phone."},
{"slug":"coworking-mallorca-playa-de-palma-platja-de-palma","city":"platja-de-palma","name":"Coworking Mallorca Playa de Palma","category":"coworking","description":"Small coworking in Can Pastilla, Playa de Palma, about 100 m from the beach and run by Island Forum. It has a 40 m2 area with long shared tables, a silent room, a sound-reduced call box, a 35 m2 terrace and a 65 m2 seminar room; fast, stable internet is advertised. Coffee, water and basic printing are included. Prices (website, excl. 21% VAT): day pass 20 EUR open room, 25 EUR silent room; 3-day pass 50 EUR.","address":"Carrer de la Garsa 6, 07610 Platja de Palma","lat":39.52962,"lng":2.73093,"website":"https://coworking-mallorca.com/en","phone":"+34 632 968 005","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"website","day_pass_price_cents":2000,"outdoor_seating":"yes","access":"registration","access_note":"Book day pass online (non-refundable, can be moved 24 h before). Open Mon-Fri 09:00-18:00; weekend opening on request."},
{"slug":"la-mar-dolca-pollenca","city":"pollenca","name":"La Mar Dolça","category":"cafe","description":"Cafe and bakery on Carrer de Sant Domingo in Pollença, open since 2010, with its own micro-roastery (Chaff Coffee Roasters), Argentine pastries baked daily and a terrace. Open weekdays 07:00-15:00. Wi-Fi is reported, but nothing confirms laptop use.","address":"Carrer de Sant Domingo 27, 07460 Pollença","lat":39.87527,"lng":3.01697,"website":"https://www.lamardolsa.com","phone":"+34 971 533965","opening_hours":"Mo-Fr 07:00-15:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Weekdays only, 07:00-15:00; closed Saturday and Sunday. Kitchen hours are listed separately on the venue site."},
{"slug":"la-molienda-pollenca-pollenca","city":"pollenca","name":"La Molienda Pollença","category":"cafe","description":"Specialty coffee and brunch shop in central Pollença, opened in 2025 by the Palma roaster La Molienda, with its own bakery counter, outdoor tables and brunch until 15:00. Free Wi-Fi is reported, but the venue makes no laptop statement. Open daily 09:00-15:00.","address":"Carrer de Cecili Metel 37, 07460 Pollença","lat":39.87545,"lng":3.01935,"website":"https://lamolienda.es/en/coffeeshops/pollenca/","opening_hours":"Mo-Su 09:00-15:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Walk-in; open daily 09:00-15:00. Some sources show Monday and Tuesday closed, but the venue lists daily opening."},
{"slug":"comunidad-inspira-pollenca","city":"pollenca","name":"Comunidad Inspira","category":"coworking","description":"Coworking and wellness community on Carrer del Fuster, on the edge of Pollença between the town and Port de Pollença. The weekday day pass (09:00-17:00) includes a hot desk, 200 Mb fibre, tea, coffee and water, plus a same-day soundproof phone pod. A bistro and yoga classes are on site. Prices (website): day 15 EUR, flex plan 100 EUR/month for 10 days; fixed-desk price not shown.","address":"Carrer del Fuster 49, 07460 Pollença","lat":39.88641,"lng":3.02974,"website":"https://inspira-pollenca.com","phone":"+34 613 35 68 70","opening_hours":"Mo-Fr 09:00-17:00","hours_source":"website","day_pass_price_cents":1500,"access":"registration","access_note":"The site mentions a waitlist, so contact them before turning up. Open weekdays only, 09:00-17:00."},
{"slug":"biblioteca-municipal-can-llobera-pollenca","city":"pollenca","name":"Biblioteca Municipal Can Llobera","category":"library","description":"Municipal library of Pollença town, at Plaça Vella 7 (Can Llobera). It lists Wi-Fi and five public computers, and laptops are welcome. Open Monday to Friday 09:00-14:00 and 16:00-20:00 and Saturday mornings; closed on Sundays.","address":"Plaça Vella 7, 07460 Pollença","lat":39.87712,"lng":3.01546,"website":"https://ajpollenca.net/ca/serveis-municipals/biblioteques","phone":"+34 971 53 01 08","opening_hours":"Mo-Fr 09:00-14:00,16:00-20:00; Sa 09:00-14:00","hours_source":"website","access":"open","access_note":"Free, no registration. Closed Sundays. No separate summer or holiday timetable is published: call 971 53 01 08 in July and August."},
{"slug":"blend-brunch-speciality-coffee-port-d-andratx","city":"port-d-andratx","name":"Blend Brunch & Speciality Coffee","category":"cafe","description":"Brunch and specialty coffee cafe on Avinguda de Gabriel Roca i Garcias by the harbour in Port d'Andratx, serving beans from three Spanish roasters as espresso, V60, batch and cold brew. Free Wi-Fi, laptop-friendly seating and outdoor tables are reported. Winter hours are Tuesday to Sunday 09:00-15:00; in summer it opens daily 09:00-16:00.","address":"Avinguda de Gabriel Roca i Garcías 1, 07157 Port d'Andratx","lat":39.54529,"lng":2.39065,"opening_hours":"Tu-Su 09:00-15:00","hours_source":"website","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Winter: closed Monday, 09:00-15:00. Summer: daily 09:00-16:00. Some sources still show daily 09:00-16:00, so check before going."},
{"slug":"yannis-cafe-port-d-andratx","city":"port-d-andratx","name":"Yannis Cafe","category":"cafe","description":"Family-run brunch and specialty coffee cafe on Carrer Cristòfol Colom, a quiet side street near the harbour in Port d'Andratx, with a terrace. Wi-Fi and a quiet atmosphere are reported, and one February 2026 review calls it suitable for remote work. The venue states no laptop policy, and opening hours conflict between sources.","address":"Carrer Cristòfol Colom 8, 07157 Port d'Andratx","lat":39.54454,"lng":2.38918,"website":"https://yanniscafe.com/","outdoor_seating":"yes","access":"open","access_note":"Daytime cafe. Opening days and hours differ between sources (most show Monday closed): check before going."},
{"slug":"coworking-port-andratx-port-d-andratx","city":"port-d-andratx","name":"Coworking Port Andratx","category":"coworking","description":"Small coworking house on Carrer Brismar in Port d'Andratx with 5 workstations, 3 independent rooms and a meeting room. Members get door-code access 24 hours a day, and the operator advertises high-speed Wi-Fi. Prices not published: day pass and meeting room rates are on request.","address":"Carrer Brismar 8, 07157 Port d'Andratx","lat":39.54323,"lng":2.38753,"website":"https://www.coworkingportandratx.com","phone":"+34 650 17 58 02","wheelchair":"yes","access":"members","access_note":"Reserve by email (info@coworkingportandratx.com) or phone. Code-based 24/7 access; reception reportedly Mon-Fri 8:30-19:00."},
{"slug":"biblioteca-municipal-d-andratx-jaume-bover-port-d-andratx","city":"port-d-andratx","name":"Biblioteca Municipal d'Andratx Jaume Bover","category":"library","description":"Public library in the historic Curia building in Andratx, part of the Consell de Mallorca library network. A first-floor study room has 26 reading places with Wi-Fi and power sockets for laptops. A basement room for group work or exam preparation is available on request from staff. Open weekdays only, with shorter hours in summer.","address":"Plaça Miquel Moner 1, 07150 Andratx","lat":39.5768,"lng":2.41809,"website":"https://andratx.es/es/asociaciones-empresas-equipamientos-e-instalaciones/biblioteca-municipal-jaume-bover","phone":"+34 971 13 60 66","opening_hours":"Mo-Fr 09:00-19:00","hours_source":"website","access":"open","access_note":"Free. Winter Mo-Fr 09:00-19:00, summer 09:00-14:00; sources differ, so call to confirm. Ask staff to use the basement study room."},
{"slug":"biblioteca-del-port-de-pollenca-port-de-pollenca","city":"port-de-pollenca","name":"Biblioteca del Port de Pollença","category":"library","description":"Municipal library on the first floor of the former Miquel Capllonch school, now the Centre Cultural, in Port de Pollença. It is open Tuesday to Saturday 10:00-13:00 and Monday to Friday 16:00-20:00. The library lists Wi-Fi and three public computers, and books can be consulted in the reading room without a card.","address":"Carrer del Metge Llopis 1, Port de Pollença","lat":39.90825,"lng":3.08195,"website":"https://ajpollenca.net/ca/serveis-municipals/biblioteques","phone":"+34 971 86 64 05","opening_hours":"Mo 16:00-20:00; Tu-Fr 10:00-13:00,16:00-20:00; Sa 10:00-13:00","hours_source":"website","access":"open","access_note":"Free; no card needed to read in the room. Sources differ on morning days and no summer timetable is published: call 971 86 64 05."},
{"slug":"biblioteca-municipal-de-santa-maria-del-cami-cas-metge-rei-santa-maria-del-cami","city":"santa-maria-del-cami","name":"Biblioteca Municipal de Santa Maria del Camí - Cas Metge Rei","category":"library","description":"Town library in the Cas Metge Rei cultural centre near the main square of Santa Maria del Camí, part of the Mallorca library network. Winter hours cover weekday mornings and afternoons plus Saturday morning; summer hours are mornings only. Study areas and Wi-Fi are not confirmed.","address":"Carrer Pare Miquel Cabot 1 (Cas Metge Rei), 07320 Santa Maria del Camí","lat":39.647,"lng":2.7782,"website":"https://ajsantamariadelcami.net/ca/adreces/biblioteca-cas-metge-rei","phone":"+34 971 14 06 65","opening_hours":"Mo-Fr 10:00-14:00,16:00-20:00; Sa 10:00-14:00","hours_source":"listing","access":"open","access_note":"Free; card only to borrow. Summer: Mo-Fr 09:00-14:00, no Saturday. Hours reported vary between sources: call 971 14 06 65 to confirm."},
{"slug":"cafe-mozart-santa-ponca-santa-ponca","city":"santa-ponca","name":"Café Mozart Santa Ponça","category":"cafe","description":"Large cafe-restaurant on the main square of Santa Ponça with a 120-seat terrace, open every day of the year and serving breakfast through to evening drinks. The venue states free Wi-Fi and battery charging for guests, and tables are spaced apart for privacy. It is tourist-oriented and does not describe itself as laptop-friendly.","address":"Plaça Santa Ponça 1, Local 17, 07180 Santa Ponça","lat":39.5149,"lng":2.48326,"website":"https://www.cafe-mozart.es/","phone":"+34 971 694 536","wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Open daily from 09:00; closing time is given as 22:30 or 24:00, so check. Busy at meal times."},
{"slug":"biblioteca-santa-ponca-galatzo-santa-ponca","city":"santa-ponca","name":"Biblioteca Santa Ponça-Galatzó","category":"library","description":"Calvià municipal library in the Galatzó residential area of Santa Ponça, a 300 m2 branch with adult and youth areas and a training and study area. It is open Monday to Friday 08:30-20:30 and Saturday mornings, and closed on Sundays. Calvià publishes reduced summer and holiday timetables separately.","address":"Avinguda Puig de Saragossa 2, local 10 (Plaça Paquita Revert), 07180 Urb. Galatzó, Santa Ponça","lat":39.52447,"lng":2.49735,"website":"https://bibliotequesdecalvia.com/","phone":"+34 971 69 41 25","opening_hours":"Mo-Fr 08:30-20:30; Sa 09:00-14:30","hours_source":"website","access":"open","access_note":"Free. Calvià posts separate summer and August timetables ('Horaris i obertes' on bibliotequesdecalvia.com): check them in July-September. About 2.5 km from Santa Ponça beach square."},
{"slug":"rayaworx-coworking-santanyi","city":"santanyi","name":"Rayaworx Coworking","category":"coworking","description":"Owner-run coworking in a restored townhouse in the centre of Santanyí, open since May 2015. Desks (some with monitors, some standing) surround a planted courtyard, with 1 Gb/s symmetric fibre advertised and a printer on site. Capacity is small, so it suits a week or a month more than a drop-in. Prices (website, Mar 2026, incl. VAT): week 99 EUR, month 290 EUR, 10-day flexible ticket 225 EUR; no day price published.","address":"Placeta de sa Porta Murada 2, 07650 Santanyí","lat":39.35492,"lng":3.12798,"website":"https://www.rayaworx.eu","phone":"+34 971 65 37 08","opening_hours":"Mo-Fr 09:00-19:00","hours_source":"website","outdoor_seating":"yes","access":"registration","access_note":"Reserve ahead: week/month tickets via online booking, day passes by email or WhatsApp. Open Mon-Fri 09:00-19:00."},
{"slug":"biblioteca-municipal-de-santanyi-santanyi","city":"santanyi","name":"Biblioteca Municipal de Santanyí","category":"library","description":"Town library on Carrer Bernat Vidal i Tomàs, next to the secondary school in Santanyí. Winter hours are a morning and an afternoon block Monday to Thursday plus a long Friday morning, with a different pattern in summer. It is described as a usable place to study or work, and Wi-Fi is reported, though facilities are not officially listed.","address":"Carrer Bernat Vidal i Tomàs 79, 07650 Santanyí","lat":39.35117,"lng":3.13359,"website":"https://ajsantanyi.net/ca/serveis-municipals/biblioteques-municipals","phone":"+34 971 65 33 94","opening_hours":"Mo-Th 10:00-13:00,16:00-19:00; Fr 09:00-14:00","hours_source":"website","access":"open","access_note":"Free, no registration. Summer: Mo,Th 10:00-13:00 and 16:30-19:00; Tu,We,Fr 09:00-14:00. Closed weekends."},
{"slug":"espai-coworking-ses-salines-ses-salines","city":"ses-salines","name":"Espai Coworking Ses Salines","category":"coworking","description":"Small coworking on Carrer Joan March in Ses Salines with seven large desks, a meeting room, a back-office area, and a kitchen corner with coffee machine, milk frother and fridge. Air conditioning runs year-round. The operator advertises wide hours and 365-day access but publishes no timetable, so details need confirming with the owner. Prices not published.","address":"Carrer Joan March 1, 07640 Ses Salines","lat":39.33825,"lng":3.05281,"website":"https://espaicoworkingsessalines.com","phone":"+34 637 304 201","access":"registration","access_note":"Contact the owner by phone or form first: hours and rates must be confirmed."},
{"slug":"coworking-minds-sineu","city":"sineu","name":"Coworking Minds","category":"coworking","description":"Coworking on a small industrial estate at the edge of Sineu, in central Mallorca, with open-space desks, a bookable meeting room and a virtual-office address. Free street parking is listed. Monthly members get key access around the clock. Prices (website, Nov 2026, excl. 21% VAT): day 19 EUR (includes coffee and water), 10 days 146 EUR, month 229 EUR.","address":"Carrer Ferrers 1 (Carrer Vial E), 07510 Sineu","lat":39.64472,"lng":3.01655,"website":"https://coworkingminds.com","phone":"+34 624 075 693","opening_hours":"Mo-Fr 09:00-18:00","hours_source":"website","day_pass_price_cents":1900,"access":"members","access_note":"Book online (day-pass widget). Open Mon-Fri 09:00-18:00; the day pass covers 08:30-17:30, first come, first served. Address also appears as Carrer Vial E 1."},
{"slug":"biblioteca-municipal-de-sineu-sineu","city":"sineu","name":"Biblioteca Municipal de Sineu","category":"library","description":"Small municipal library in the centre of Sineu, part of the Consell de Mallorca library network. In winter it is open every weekday afternoon from 16:00 to 20:00, with late-morning openings on Tuesday, Wednesday and Friday. Summer hours differ and are mornings on Tuesday, Thursday and Friday.","address":"Carrer de Sant Francesc 10, 07510 Sineu","lat":39.64377,"lng":3.01079,"website":"https://portal.conselldemallorca.net/web/16689/17","phone":"+34 971 52 07 67","opening_hours":"Mo,Th 16:00-20:00; Tu,We,Fr 11:00-13:30,16:00-20:00","hours_source":"website","access":"open","access_note":"Free, no registration. Summer: Tu,Th,Fr 10:00-14:00; Mo,We 16:00-20:00. Sources differ on the morning days: call before going."},
{"slug":"coccum-specialty-coffee-brunch-soller","city":"soller","name":"Coccum Specialty Coffee & Brunch","category":"cafe","description":"Very small specialty coffee and brunch cafe on Carrer d'Isabel II near the train station in Sóller, serving Jaleo-roasted coffee, toasts, focaccia and baked goods. Free Wi-Fi and laptop-friendly seating are reported, and a review mentions USB chargers. With only a handful of tables it fills quickly. Price level is roughly EUR 1-10 per item.","address":"Carrer d'Isabel II 2, 07100 Sóller","lat":39.76555,"lng":2.71465,"wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Walk-in. Reported hours Tuesday to Saturday 09:00-15:30, closed Sunday and Monday. Very small room, so seats fill quickly."},
{"slug":"imperfectas-specialty-coffee-soller","city":"soller","name":"Imperfectas Specialty Coffee","category":"cafe","description":"Small brunch cafe and bakery on Carrer de sa Mar in Sóller, serving specialty coffee, creative brunch dishes and many gluten-free and vegan options, with a few outdoor tables and a back patio for bikes. Free Wi-Fi and laptop use are reported by one source only, and opening hours differ between sources.","address":"Carrer de sa Mar 75, 07100 Sóller","lat":39.76857,"lng":2.71191,"wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Walk-in. Opening days and hours differ between sources (Wednesday closed; some also show Tuesday closed): check before going. Instagram: @imperfectas_soller."},
{"slug":"biblioteca-municipal-de-soller-soller","city":"soller","name":"Biblioteca Municipal de Sóller","category":"library","description":"Sóller's municipal library, in a temporary home on the ground floor of the Hospital building since June 2025. From 14 September 2026 it announced regular hours of 10:00 to 20:00 on weekdays, with no midday break. Staff mention Wi-Fi, two public computers and a study room, and laptops are welcome.","address":"Carrer de Batac 25 (temporary site in the Hospital building, Carrer de sa Lluna), 07100 Sóller","lat":39.76709,"lng":2.71718,"website":"https://ajsoller.net/ca/cultura","phone":"+34 971 63 03 88","opening_hours":"Mo-Fr 10:00-20:00","hours_source":"website","access":"open","access_note":"Free, no registration. Temporary site while the Escolàpies building is renovated. Summer hours are unconfirmed: call ahead or check the location before travelling."},
{"slug":"barbaflorida-cafe-valldemossa","city":"valldemossa","name":"Barbaflorida cafè","category":"cafe","description":"Small specialty coffee cafe on Plaça Cartoixa in Valldemossa, opposite the Charterhouse, with V60, batch brew and cold brew plus breakfast, lunch and a terrace on the square. Free Wi-Fi and laptop-friendly seating are reported. Daytime hours only, with most sources showing Tuesday and Wednesday closed. The small interior is loud, so the terrace is preferred.","address":"Plaça Cartoixa 19, 07170 Valldemossa","lat":39.7098,"lng":2.62238,"wheelchair":"yes","outdoor_seating":"yes","access":"open","access_note":"Most sources show closed Tuesday and Wednesday, 10:00-16:00 otherwise: confirm. Booking for lunch is advised by WhatsApp."}
]$items$::jsonb) as x(
      slug text, city text, name text, category text, description text, address text,
      lat double precision, lng double precision, website text, phone text, opening_hours text,
      hours_source text, day_pass_price_cents integer, wheelchair text, outdoor_seating text,
      access text, access_note text, address_unconfirmed boolean
    )
  loop
    select id into v_city from public.cities where slug = it.city;
    if v_city is null then
      continue;
    end if;

    v_id := null;
    v_osm := false;
    select id, (source = 'osm') into v_id, v_osm from public.places where slug = it.slug and category = it.category;
    v_osm := coalesce(v_osm, false);
    if v_id is null then
      select p.id into v_id
        from public.places p
       where p.category = it.category
         and p.source = 'osm'
         and p.status <> 'archived'
         and not (p.id = any(v_matched))
         and public.approx_distance_km(p.lat, p.lng, it.lat, it.lng) < 0.2
         and (
           public.approx_distance_km(p.lat, p.lng, it.lat, it.lng) < 0.015
           or (p.category = 'library' and public.approx_distance_km(p.lat, p.lng, it.lat, it.lng) < 0.06)
           or pg_temp.mallorca_nk(p.name) like '%' || pg_temp.mallorca_nk(it.name) || '%'
           or pg_temp.mallorca_nk(it.name) like '%' || pg_temp.mallorca_nk(p.name) || '%'
         )
       order by public.approx_distance_km(p.lat, p.lng, it.lat, it.lng)
       limit 1;
      v_osm := v_id is not null;
    end if;

    if v_id is null then
      insert into public.places (
        city_id, slug, name, category, status, source, description, address, lat, lng, website, phone,
        opening_hours, hours_source, day_pass_price_cents, wheelchair, outdoor_seating, access, access_note,
        address_unconfirmed, last_verified_at
      ) values (
        v_city, it.slug, it.name, it.category, 'published', 'admin', it.description, it.address, it.lat, it.lng,
        it.website, it.phone, it.opening_hours, it.hours_source, it.day_pass_price_cents,
        coalesce(it.wheelchair, 'unknown'), coalesce(it.outdoor_seating, 'unknown'), it.access, it.access_note,
        coalesce(it.address_unconfirmed, false), date '2026-11-15'
      );
    elsif v_osm then
      v_matched := array_append(v_matched, v_id);
      v_lock := array['name', 'lat', 'lng'];
      if it.address is not null then v_lock := array_append(v_lock, 'address'); end if;
      if it.website is not null then v_lock := array_append(v_lock, 'website'); end if;
      if it.phone is not null then v_lock := array_append(v_lock, 'phone'); end if;
      if it.opening_hours is not null then v_lock := array_append(v_lock, 'opening_hours'); end if;
      if it.wheelchair is not null and it.wheelchair <> 'unknown' then v_lock := array_append(v_lock, 'wheelchair'); end if;
      if it.outdoor_seating is not null and it.outdoor_seating <> 'unknown' then v_lock := array_append(v_lock, 'outdoor_seating'); end if;
      update public.places set
        city_id = v_city,
        name = it.name,
        description = it.description,
        address = coalesce(it.address, address),
        lat = it.lat,
        lng = it.lng,
        website = coalesce(it.website, website),
        phone = coalesce(it.phone, phone),
        opening_hours = coalesce(it.opening_hours, opening_hours),
        hours_source = case when it.opening_hours is not null then it.hours_source else hours_source end,
        day_pass_price_cents = coalesce(it.day_pass_price_cents, day_pass_price_cents),
        wheelchair = case when it.wheelchair is not null and it.wheelchair <> 'unknown' then it.wheelchair else wheelchair end,
        outdoor_seating = case when it.outdoor_seating is not null and it.outdoor_seating <> 'unknown' then it.outdoor_seating else outdoor_seating end,
        access = it.access,
        access_note = it.access_note,
        address_unconfirmed = coalesce(it.address_unconfirmed, false),
        status = case when status = 'needs_review' then 'published' else status end,
        last_verified_at = date '2026-11-15',
        locked_fields = (select coalesce(array_agg(distinct f), '{}') from unnest(locked_fields || v_lock) f)
      where id = v_id;
    else
      update public.places set
        name = it.name,
        description = it.description,
        address = it.address,
        lat = it.lat,
        lng = it.lng,
        website = it.website,
        phone = it.phone,
        opening_hours = it.opening_hours,
        hours_source = it.hours_source,
        day_pass_price_cents = it.day_pass_price_cents,
        wheelchair = coalesce(it.wheelchair, 'unknown'),
        outdoor_seating = coalesce(it.outdoor_seating, 'unknown'),
        access = it.access,
        access_note = it.access_note,
        address_unconfirmed = coalesce(it.address_unconfirmed, false),
        last_verified_at = date '2026-11-15'
      where id = v_id and source = 'admin';
    end if;
  end loop;
  perform set_config('cosurfing.bulk', 'off', true);

  for v_city in select id from public.cities where slug in (
    'palma', 'soller', 'pollenca', 'port-de-pollenca', 'alcudia', 'port-d-andratx', 'peguera', 'santa-ponca',
    'palmanova', 'valldemossa', 'esporles', 'santa-maria-del-cami', 'inca', 'sineu', 'arta', 'cala-ratjada',
    'manacor', 'felanitx', 'santanyi', 'ses-salines', 'campos', 'platja-de-palma'
  ) loop
    perform public.refresh_city_stats(v_city);
  end loop;
end
$mallorca$;
